terms.medium_def:
A man living at the time of United Monarchy, only mentioned at 1Ki.4.10; 
only referred to as Hesed (חֶ֫סֶד); 
father of Ben-hesed. § father of or maybe a commissary officer under Solomon

A man from the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.3.20; 
only referred to as Hasadiah (חֲסַדְיָה); 
son of Zerubbabel; 
a brother of Meshullam, Hananiah, Shelomith, Hashubah, Ohel, Berechiah, Jushab-hesed, Abiud. § a son of Zerubbabel

A location first mentioned at Rev.1.11; 
only referred to as Philadelphia (Φιλαδέλφεια). § Philadelphia, "love of brother/sister" 
Philadelphia, a city of Lydia, near Mount Tmolus, Rev. 1:11; 3:7*

Tetrarch Herod Philip I living at the time of the New Testament, first mentioned at Mat.14.3; 
referred to as Philip or [ ] (KJV= Philip) (Φίλιππος); 
son of Herod 'the Great'; 
a brother of Ethnarch Herod Archelaus, Herod Antipas I and Herod Philip II; 
husband of Herodias; 
father of Salome.

Tetrarch Herod Philip II living at the time of the New Testament, only mentioned at Luk.3.1; 
only referred to as Philip (Φίλιππος); 
son of Herod 'the Great'; 
a brother of Ethnarch Herod Archelaus, Herod Antipas I and Herod Philip I.

A king of Judah living at the time of United Monarchy, first mentioned at Rut.4.17; 
referred to as David or [ ] (KJV, NIV= David) (דָּוִד), or David (Δαυείδ, Δαυίδ, Δαβίδ); 
son of Jesse and Nahash; 
a brother of Eliab, Abinadab, Shimeah, Zeruiah, Abigail(?), Nethanel, Raddai, Ozem and Elihu; 
husband of Michal, Abigail, Ahinoam, Maacah, Haggith, Abital, Eglah and Bathsheba; 
father of Amnon, Chileab, Absalom, Adonijah, Shephatiah, Ithream, Shammua, Shobab, Nathan, Solomon, Ibhar, Elishua, Nepheg, Japhia, Elishama, Eliada, Eliphelet, Tamar, Elpelet, Nogah and Jerimoth. § youngest son of Jesse and second king of Israel

A man living at the time of United Monarchy, first mentioned at 2Sa.23.9; 
referred to as Dodo (דּוֹדוֹ), or Dodai (דּוֹדַי); 
father of Eleazar.

A man living at the time of United Monarchy, first mentioned at 2Sa.23.24; 
only referred to as Dodo (דּוֹדוֹ); 
father of Elhanan.

A man living before Israel's Monarchy, only mentioned at Jdg.10.1; 
only referred to as Dodo (דּוֹדוֹ); 
father of Puah.

A man living at the time of Divided Monarchy, only mentioned at 2Ch.20.37; 
only referred to as Dodavahu (דּוֹדָוָהוּ); 
father of Eliezer. § a man of Mareshah in Judah, the father of Eliezer, who denounced Jehoshaphat's alliance with Ahaziah

A man living at the time of United Monarchy, first mentioned at 2Sa.23.9; 
referred to as Dodo (דּוֹדוֹ), or Dodai (דּוֹדַי); 
father of Eleazar. § an Ahohite who commanded the course of the second month; probably the same as 'Dodo'

A woman of the Moabites living before Israel's Monarchy, first mentioned at Rut.1.4; 
referred to as Ruth (רוּת), or Ruth (Ῥούθ); 
wife of Mahlon and Boaz; 
mother of Obed. § daughter-in-law of Naomi, wife of Boaz, and grandmother of David

A man of the Edomites living at the time of the Patriarchs, first mentioned at Gen.36.4; 
only referred to as Reuel (רְעוּאֵל); 
a son of Esau and Mahalath; 
half-brother of: Eliphaz, Jeush, Jalam and Korah; 
father of Nahath, Zerah, Shammah and Mizzah.

A man living at the time of the Patriarchs, first mentioned at Gen.11.18; 
referred to as Reu (רְעוּ), or Reu (KJV= Ragau) (Ῥαγαῦ); 
a son of Peleg; 
father of Serug. § son of Peleg and an ancestor of Abraham

A man living at the time of Egypt and Wilderness, first mentioned at Exo.2.18; 
referred to as Jethro (יִתְרוֹ), or Jethro (יֶ֫תֶר), or Jothor (LXX) (Ιωθώρ), or Reuel (KJV= Raguel) or Reuel (רְעוּאֵל); 
father of Zipporah and Hobab.

A man living at the time of Exile and Return, only mentioned at 1Ch.9.8; 
only referred to as Reuel (רְעוּאֵל); 
a son of Ibnijah; 
father of Shephatiah.

A man living at the time of Egypt and Wilderness, first mentioned at Num.1.14; 
referred to as Deuel (דְּעוּאֵל), or Reuel (רְעוּאֵל); 
father of Eliasaph.

A man from the tribe of Judah living at the time of Divided Monarchy, first mentioned at 1Ch.3.23; 
only referred to as Elioenai (אֶלְיוֹעֵינַי); 
son of Neariah; 
a brother of Hizkiah and Azrikam; 
father of Hodaviah, Eliashib, Pelaiah, Akkub, Johanan, Delaiah and Anani.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.26.3; 
only referred to as Eliehoenai (אֶלְיְהוֹעֵינַי); 
son of Meshelemiah; 
a brother of Zechariah, Jediael, Zebadiah, Jathniel, Elam and Jehohanan.

A man living at the time of Exile and Return, only mentioned at Ezr.8.4; 
only referred to as Eliehoenai (אֶלְיְהוֹעֵינַי); 
a son of Zerahiah.

A man from the tribe of Benjamin living at the time of Egypt and Wilderness, only mentioned at 1Ch.7.8; 
only referred to as Elioenai (אֶלְיוֹעֵינַי); 
son of Becher; 
a brother of Zemirah, Joash, Eliezer, Omri, Jeremoth, Abijah, Anathoth and Alemeth.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.20; 
only referred to as Elienai (אֱלִיעֵינַי); 
son of Shimei; 
a brother of Jakim, Zichri, Zabdi, Zillethai, Eliel, Adaiah, Beraiah and Shimrath. § a Benjamite

A location first mentioned at Gen.19.38; 
referred to as Ammon or Ammonite (עַמּוֹן), or Ammon or Ammonite (עַמּוֹנִי), or Ammonitess (עַמּוֹנִית), or Rabbah (KJV= Rabbath) (רַבָּה). §Someone from Ammon, Ammonite, of Ammon "tribal"
descendants of Ammon and inhabitants of Ammon

A man from the tribe of Judah living at the time of Egypt and Wilderness, first mentioned at Exo.6.23; 
referred to as Amminadab (עַמִּינָדָב), or Amminadab (Ἀμιναδάβ); 
a son of Ram; 
father of Elisheba and Nahshon.

A man from the tribe of Ephraim living at the time of Egypt and Wilderness, first mentioned at Num.1.10; 
only referred to as Ammihud (עַמִּיהוּד); 
a son of Ladan; 
father of Elishama.

A man living at the time of Egypt and Wilderness, first mentioned at Num.1.12; 
only referred to as Ammishaddai (עַמִּישַׁדָּ֑י); 
father of Ahiezer. § father of Ahiezer, prince of the tribe of Dan at the time of the exodus

A man living at the time of United Monarchy, first mentioned at 2Sa.9.4; 
only referred to as Ammiel (עַמִּיאֵל); 
father of Machir.

A man from the tribe of Judah living at the time of the New Testament, first mentioned at Mat.1.1; 
referred to as Jesus or "he" or Lord or Christ or [ ] (Ἰησοῦς), or Christ or [ ] (Χριστός), or Christian (Χριστιανός), or Immanuel (KJV= Emmanuel) (עִמָּנוּאֵל), or Immanuel (Ἐμμανουήλ); 
son of Joseph and Mary; 
a brother of James, Joses, Simon and Jude. § symbolic and prophetic name of the Messiah, the Christ, prophesying that He would be born of a virgin and would be 'God with us'

People from Meunit(?) of the Canaanites, first mentioned at 1Ch.4.41; 
referred to as Meunites or Meunite (KJV= Mehunite) (מְעוּנִים), or Meunite (KJV= "beside") (עַמּוֹנִי). § Ammonite, of Ammon "tribal"
descendants of Ammon and inhabitants of Ammon

A man living at the time of Egypt and Wilderness, only mentioned at Num.13.12; 
only referred to as Ammiel (עַמִּיאֵל); 
a son of Gemalli.

A man from the tribe of Levi living at the time of United Monarchy, only mentioned at 1Ch.26.5; 
only referred to as Ammiel (עַמִּיאֵל); 
son of Obed-edom; 
a brother of Shemaiah, Jehozabad, Joah, Sachar, Nethanel, Issachar and Peullethai.

A man living at the time of United Monarchy, first mentioned at 2Sa.11.3; 
referred to as Eliam (אֱלִיעָם), or Ammiel (עַמִּיאֵל); 
father of Bathsheba.

A man living at the time of Egypt and Wilderness, only mentioned at Num.34.20; 
only referred to as Ammihud (עַמִּיהוּד); 
father of Shemuel.

A man living at the time of Egypt and Wilderness, only mentioned at Num.34.28; 
only referred to as Ammihud (עַמִּיהוּד); 
father of Pedahel.

A man living at the time of United Monarchy, only mentioned at 2Sa.13.37; 
referred to as Ammihud (עַמִּיהוּד), or Ammihur (=Ketiv) (עַמִּיהוּד); 
father of Talmai.

A man from the tribe of Judah living at the time of Exile and Return, only mentioned at 1Ch.9.4; 
only referred to as Ammihud (עַמִּיהוּד); 
a son of Omri; 
father of Uthai.

A man living at the time of United Monarchy, only mentioned at 1Ch.27.6; 
only referred to as Ammizabad (עַמִּיזָבָד); 
a son of Benaiah. § son of Benaiah, who commanded the 3rd division of David's army

A man from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at Exo.6.18; 
referred to as Izhar or Izhar (KJV= Izehar) (יִצְהָר), or Izharite (יִצְהָרִי), or Izhar (עַמִּינָדָב); 
son of Kohath; 
a brother of Amram, Hebron and Uzziel; 
father of Korah, Nepheg, Zichri and Shelomith.

A man living at the time of United Monarchy, only mentioned at 2Sa.13.37; 
referred to as Ammihud (עַמִּיהוּד), or Ammihur (=Ketiv) (עַמִּיהוּד); 
father of Talmai. § a ruler of Syria

A man from the tribe of Judah living before Israel's Monarchy, first mentioned at 1Sa.27.10; 
referred to as Jerahmeel (יְרַחְמְאֵל), or Jerahmeelite (יְרַחְמְאֵלִי); 
son of Hezron; 
a brother of Ram, Caleb, Segub and Ashhur; 
husband of Atarah; 
father of Ram, Bunah, Oren, Ozem, Ahijah and Onam.

A man from the tribe of Levi living at the time of United Monarchy, first mentioned at 1Sa.1.1; 
only referred to as Jeroham (יְרֹחָם); 
a son of Elihu; 
father of Elkanah.

A priest from the tribe of Levi living at the time of Exile and Return, first mentioned at 1Ch.9.12; 
only referred to as Jeroham (יְרֹחָם); 
a son of Pelaliah; 
father of Adaiah.

A man from the tribe of Judah living before Israel's Monarchy, first mentioned at 1Sa.27.10; 
referred to as Jerahmeel (יְרַחְמְאֵל), or Jerahmeelite (יְרַחְמְאֵלִי); 
son of Hezron; 
a brother of Ram, Caleb, Segub and Ashhur; 
husband of Atarah; 
father of Ram, Bunah, Oren, Ozem, Ahijah and Onam. § Jerahmeelites , of Jerahmeel "may God have pity"
the descendants of Jerahmeel, the great grandson of Judah

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.27; 
only referred to as Jeroham (יְרֹחָם); 
father of Shamsherai, Shehariah, Athaliah, Jaareshiah, Elijah and Zichri.

A man living at the time of Exile and Return, only mentioned at 1Ch.9.8; 
only referred to as Jeroham (יְרֹחָם); 
father of Ibneiah.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.12.7; 
only referred to as Jeroham (יְרֹחָם); 
father of Joelah, Zebadiah.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.27.22; 
only referred to as Jeroham (יְרֹחָם); 
father of Azarel.

A man living at the time of Divided Monarchy, only mentioned at 2Ch.23.1; 
only referred to as Jeroham (יְרֹחָם); 
father of Azariah.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.24.29; 
only referred to as Jerahmeel (יְרַחְמְאֵל); 
a son of Kish.

A man living at the time of Divided Monarchy, only mentioned at Jer.36.26; 
only referred to as Jerahmeel (יְרַחְמְאֵל); 
son of Hammelech; 
a brother of Malchijah.

A man living at the time of Exile and Return, only mentioned at Neh.3.17; 
only referred to as Rehum (רְחוּם); 
a son of Bani. § a commander who wrote a letter to the king Artaxerxes in which he opposed the rebuilding of Jerusalem

A man from the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.2.44; 
only referred to as Raham (רַ֫חַם); 
a son of Shema; 
father or founder of Jorkeam. § a Judaite, son of Shema, father of Jorkoam, and of the descendants of Caleb

A man living at the time of Divided Monarchy, only mentioned at 1Ch.27.21; 
only referred to as Iddo (יִדּוֹ); 
a son of Zechariah.

A woman living at the time of Divided Monarchy, only mentioned at 2Ki.22.1; 
only referred to as Jedidah (יְדִידָה); 
a daughter of Adaiah; 
wife of Amon; 
mother of Josiah. § the wife of king Amon and mother of king Josiah

A king of Judah living at the time of United Monarchy, first mentioned at 2Sa.5.14; 
referred to as Solomon (שְׁלֹמֹה), or Jedidiah (יְדִידְיָה), or Solomon (Σολομών, Σαλωμών); 
son of David and Bathsheba; 
a brother of Shammua, Shobab and Nathan; 
half-brother of: Amnon, Chileab, Absalom, Adonijah, Shephatiah, Ithream, Ibhar, Elishua, Nepheg, Japhia, Elishama, Eliada, Eliphelet, Tamar, Elpelet, Nogah and Jerimoth; 
husband of daughter_of_Pharaoh and Naamah; 
father of Taphath, Basemath and Rehoboam. § the name given to Solomon through Nathan the prophet
